import os,subprocess,re,json,shutil
env=os.environ.copy();env['DISPLAY']=':0'
windows=[]
if shutil.which('xprop'):
 p=subprocess.run(['xprop','-root','_NET_CLIENT_LIST'],env=env,capture_output=True,text=True,timeout=10)
 for wid in re.findall(r'0x[0-9a-fA-F]+',p.stdout):
  q=subprocess.run(['xprop','-id',wid,'WM_CLASS','_NET_WM_NAME'],env=env,capture_output=True,text=True,timeout=5)
  if any(x in q.stdout.lower() for x in ['eeschema','kicad']):windows.append(q.stdout)
print(json.dumps({'host':os.uname().nodename,'kicad_windows':windows,'xprop_available':bool(shutil.which('xprop'))}))
